package camellia

import (
	"encoding/hex"
	"fmt"
	"testing"
	"unsafe"
)

var originalBlockTraces = []struct {
	Key, Plain, State, Cipher string
	Effective                 int
}{
	{"00254a6f94b9de03284d7297bce1062b", "000b16212c37424d58636e79848f9aa5", "", "34d8acc456207aa3d964cc0d2abd7543", 0},
	{"13385d82a7ccf1163b6085aacff4193e", "010c17222d38434e59646f7a85909ba6", "", "a7a1e88967b3736320f5d0943e9f4c43", 0},
	{"00254a6f94b9de03284d7297bce1062b50759abfe4092e53", "000b16212c37424d58636e79848f9aa5", "", "099cdf38cb13b50947aa2ba48ef6cfe0", 0},
	{"13385d82a7ccf1163b6085aacff4193e6388add2f71c4166", "010c17222d38434e59646f7a85909ba6", "", "7aec040a2c690decc30a9c69e191d0f4", 0},
	{"00254a6f94b9de03284d7297bce1062b50759abfe4092e53789dc2e70c31567b", "000b16212c37424d58636e79848f9aa5", "", "db732d0a65ad3217776c1ceb1e2247bf", 0},
	{"13385d82a7ccf1163b6085aacff4193e6388add2f71c41668bb0d5fa1f44698e", "010c17222d38434e59646f7a85909ba6", "", "c5063970d9550f9ceaf33114607c80bc", 0},
}

func TestOriginalBlockMachineCode(t *testing.T) {
	for i, row := range originalBlockTraces {
		t.Run(fmt.Sprint(i), func(t *testing.T) {
			key, _ := hex.DecodeString(row.Key)
			plain, _ := hex.DecodeString(row.Plain)
			want, _ := hex.DecodeString(row.Cipher)
			block, e := RMycR7V(key)
			if e != nil {
				t.Fatal(e)
			}
			state := block.(*gaC3UK)
			if unsafe.Sizeof(*state) != 304 {
				t.Fatal("RTTI layout")
			}
			if hex.EncodeToString(unsafe.Slice((*byte)(unsafe.Pointer(state)), 304)) != row.State {
				t.Fatal("key schedule does not match original machine code")
			}
			out := make([]byte, len(plain))
			block.Encrypt(out, plain)
			if hex.EncodeToString(out) != row.Cipher {
				t.Fatalf("cipher=%x want%x", out, want)
			}
			block.Decrypt(out, out)
			if hex.EncodeToString(out) != row.Plain {
				t.Fatal("decrypt")
			}
		})
	}
}
